{"path":"src/lib/time.ts","content":"export type TimeFormat = '12h' | '24h';

interface Parts { year: number; month: number; day: number; hour: number; minute: number; second: number; }

const cache = new Map<string, Intl.DateTimeFormat>();
function fmt(tz: string): Intl.DateTimeFormat {
  let f = cache.get(tz);
  if (!f) {
    f = new Intl.DateTimeFormat('en-US', {
      timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23',
    });
    cache.set(tz, f);
  }
  return f;
}

export function getParts(tz: string, date: Date): Parts {
  const p: Record<string, number> = {};
  for (const part of fmt(tz).formatToParts(date)) {
    if (part.type !== 'literal') p[part.type] = Number(part.value);
  }
  return { year: p.year, month: p.month, day: p.day, hour: p.hour % 24, minute: p.minute, second: p.second };
}

/** UTC offset in minutes for `tz` at instant `date` (DST-aware, fractional-safe). */
export function getOffsetMinutes(tz: string, date: Date): number {
  const p = getParts(tz, date);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  return Math.round((asUtc - Math.floor(date.getTime() / 1000) * 1000) / 60000);
}

export function formatOffset(minutes: number): string {
  const sign = minutes < 0 ? '−' : '+';
  const abs = Math.abs(minutes);
  const h = Math.floor(abs / 60);
  const m = abs % 60;
  return m === 0 ? `UTC${sign}${h}` : `UTC${sign}${h}:${String(m).padStart(2, '0')}`;
}

/** UTC instant at which `tz` local time is y-m-d hour:00. Two-pass for DST edges. */
export function zonedHourToUtc(year: number, month: number, day: number, hour: number, tz: string): Date {
  const guess = Date.UTC(year, month - 1, day, hour, 0, 0);
  let utc = guess - getOffsetMinutes(tz, new Date(guess)) * 60000;
  utc = guess - getOffsetMinutes(tz, new Date(utc)) * 60000;
  return new Date(utc);
}

export function isAwake(hour: number, wake: number, sleep: number): boolean {
  if (wake === sleep) return true;
  if (wake < sleep) return hour >= wake && hour < sleep;
  return hour >= wake || hour < sleep;
}

export function formatHour(hour: number, format: TimeFormat): string {
  const h = ((hour % 24) + 24) % 24;
  if (format === '24h') return `${String(h).padStart(2, '0')}:00`;
  const suffix = h < 12 ? 'am' : 'pm';
  const display = h % 12 === 0 ? 12 : h % 12;
  return `${display}${suffix}`;
}

/** Short label inside a cell, e.g. "9a", "12p", "09". */
export function formatCellHour(hour: number, format: TimeFormat): string {
  if (format === '24h') return String(hour).padStart(2, '0');
  const suffix = hour < 12 ? 'a' : 'p';
  const display = hour % 12 === 0 ? 12 : hour % 12;
  return `${display}${suffix}`;
}

export interface Range { start: number; end: number; } // end exclusive

export function toRanges(flags: boolean[]): Range[] {
  const ranges: Range[] = [];
  let start: number | null = null;
  for (let i = 0; i < 24; i++) {
    if (flags[i] && start === null) start = i;
    if (!flags[i] && start !== null) { ranges.push({ start, end: i }); start = null; }
  }
  if (start !== null) ranges.push({ start, end: 24 });
  return ranges;
}

export function formatRange(r: Range, format: TimeFormat): string {
  return `${formatHour(r.start, format)} — ${formatHour(r.end, format)}`;
}
"}

{"path":"src/components/CityPicker.tsx","content":"import { useMemo, useRef, useState } from 'react';
import { CITIES } from '../data/cities';

interface Props {
  selectedIds: string[];
  onAdd: (id: string) => void;
}

export default function CityPicker({ selectedIds, onAdd }: Props) {
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    const available = CITIES.filter((c) => !selectedIds.includes(c.id));
    if (!q) return available;
    return available.filter(
      (c) => c.name.toLowerCase().includes(q) || c.country.toLowerCase().includes(q) || c.region.toLowerCase().includes(q),
    );
  }, [query, selectedIds]);

  const pick = (id: string) => {
    onAdd(id);
    setQuery('');
    setOpen(false);
    inputRef.current?.focus();
  };

  return (
    <div className="picker">
      <label className="picker-label" htmlFor="city-search">Add a city</label>
      <div className="picker-box">
        <input
          id="city-search"
          ref={inputRef}
          value={query}
          placeholder="Search by city or country…"
          onChange={(e) => { setQuery(e.target.value); setOpen(true); }}
          onFocus={() => setOpen(true)}
          onBlur={() => window.setTimeout(() => setOpen(false), 140)}
          autoComplete="off"
        />
        {query && (
          <button type="button" className="picker-clear" aria-label="Clear search" onClick={() => setQuery('')}>×</button>
        )}
      </div>
      {open && (
        <ul className="picker-list" role="listbox" aria-label="Available cities">
          {results.length === 0 && <li className="picker-empty">No matching cities left to add.</li>}
          {results.map((c) => (
            <li key={c.id}>
              <button type="button" className="picker-item" onMouseDown={(e) => e.preventDefault()} onClick={() => pick(c.id)}>
                <span className="picker-city">{c.name}</span>
                <span className="picker-meta">{c.country} · {c.region}</span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
"}

{"path":"src/components/OverlapSummary.tsx","content":"import type { City } from '../data/cities';
import { formatRange, toRanges, type TimeFormat } from '../lib/time';

export type Mode = 'meeting' | 'base';

interface Props {
  mode: Mode;
  cities: City[];
  meetingFlags: boolean[];
  baseFlags: Map<string, boolean[]>;
  format: TimeFormat;
}

function Ranges({ flags, format }: { flags: boolean[]; format: TimeFormat }) {
  const ranges = toRanges(flags);
  if (ranges.length === 0) return null;
  return (
    <span className="range-badges">
      {ranges.map((r) => (
        <span key={r.start} className="range-badge">{formatRange(r, format)}</span>
      ))}
    </span>
  );
}

export default function OverlapSummary({ mode, cities, meetingFlags, baseFlags, format }: Props) {
  if (cities.length < 2) {
    return (
      <section className="summary" aria-live="polite">
        <p className="summary-line muted-line">Add at least one more city to see overlap.</p>
      </section>
    );
  }
  const ref = cities[0];

  if (mode === 'meeting') {
    const count = meetingFlags.filter(Boolean).length;
    return (
      <section className="summary" aria-live="polite">
        {count > 0 ? (
          <p className="summary-line">
            <strong className="summary-count">{count}h overlap</strong>
            <span className="summary-detail">when everyone is awake, in {ref.name} time:</span>
            <Ranges flags={meetingFlags} format={format} />
          </p>
        ) : (
          <p className="summary-line warning">⚠ No common awake hours across all {cities.length} cities with this sleep schedule. Try widening the awake window.</p>
        )}
      </section>
    );
  }

  return (
    <section className="summary" aria-live="polite">
      <ul className="summary-list">
        {cities.slice(1).map((city) => {
          const flags = baseFlags.get(city.id) ?? [];
          const count = flags.filter(Boolean).length;
          return (
            <li key={city.id} className="summary-line">
              <strong className="summary-city">{ref.name} × {city.name}</strong>
              {count > 0 ? (
                <>
                  <span className="summary-count">{count}h overlap</span>
                  <Ranges flags={flags} format={format} />
                </>
              ) : (
                <span className="warning">⚠ No overlap with {ref.name}</span>
              )}
            </li>
          );
        })}
      </ul>
    </section>
  );
}
"}

{"path":"src/components/Grids.tsx","content":"import type { City } from '../data/cities';
import { formatCellHour, formatHour, formatOffset, getOffsetMinutes, type TimeFormat } from '../lib/time';

export interface CellInfo { localHour: number; dayShift: number; awake: boolean; overlap: boolean; }

interface GridProps {
  cities: City[];
  matrix: CellInfo[][]; // [cityIndex][refHour]
  format: TimeFormat;
  now: Date;
  currentRefHour: number;
  onPromote: (id: string) => void;
  onRemove: (id: string) => void;
}

function cellClass(cell: CellInfo): string {
  if (!cell.awake) return 'cell cell-sleep';
  return cell.overlap ? 'cell cell-overlap' : 'cell cell-awake';
}

function CityLabel({ city, isRef, now, onPromote }: { city: City; isRef: boolean; now: Date; onPromote: (id: string) => void }) {
  return (
    <div className="city-label">
      <button
        type="button"
        className="city-name"
        title={isRef ? 'Reference city' : `Make ${city.name} the reference city`}
        onClick={() => onPromote(city.id)}
      >
        {city.name}
      </button>
      <span className="city-sub">
        {city.country}
        {isRef && <span className="ref-badge">REF</span>}
      </span>
      <span className="city-offset">{formatOffset(getOffsetMinutes(city.tz, now))}</span>
    </div>
  );
}

export function DesktopGrid({ cities, matrix, format, now, currentRefHour, onPromote, onRemove }: GridProps) {
  return (
    <div className="grid-wrap desktop-grid" role="table" aria-label="Timezone overlap grid">
      <div className="d-row d-header" role="row">
        <div className="d-corner">City</div>
        {Array.from({ length: 24 }, (_, h) => (
          <div key={h} className={`d-hour${h === currentRefHour ? ' is-now' : ''}`} role="columnheader" title={formatHour(h, format)}>
            {formatCellHour(h, format)}
          </div>
        ))}
        <div className="d-corner-end" aria-hidden="true" />
      </div>
      {cities.map((city, ci) => (
        <div key={city.id} className="d-row" role="row">
          <CityLabel city={city} isRef={ci === 0} now={now} onPromote={onPromote} />
          {matrix[ci].map((cell, h) => (
            <div
              key={h}
              role="cell"
              className={`${cellClass(cell)}${h === currentRefHour ? ' is-now-col' : ''}`}
              title={`${city.name}: ${formatHour(cell.localHour, format)}${cell.dayShift !== 0 ? (cell.dayShift > 0 ? ' (next day)' : ' (previous day)') : ''}`}
            >
              <span className="cell-hour">{formatCellHour(cell.localHour, format)}</span>
              {cell.dayShift !== 0 && <span className="cell-shift">{cell.dayShift > 0 ? '+1' : '−1'}</span>}
            </div>
          ))}
          <button
            type="button"
            className="remove-btn"
            aria-label={`Remove ${city.name}`}
            title={`Remove ${city.name}`}
            onClick={() => onRemove(city.id)}
            disabled={cities.length <= 1}
          >
            ×
          </button>
        </div>
      ))}
    </div>
  );
}

export function MobileGrid({ cities, matrix, format, now, currentRefHour, onPromote, onRemove }: GridProps) {
  return (
    <div className="grid-wrap mobile-grid" role="table" aria-label="Timezone overlap grid">
      <div className="m-header" style={{ gridTemplateColumns: `52px repeat(${cities.length}, 1fr)` }}>
        <div className="m-corner">{cities[0] ? formatCellHour(currentRefHour, format) : ''}</div>
        {cities.map((city, ci) => (
          <div key={city.id} className="m-city">
            <button type="button" className="city-name m-name" onClick={() => onPromote(city.id)} title={ci === 0 ? 'Reference city' : `Make ${city.name} the reference`}>
              {city.name}
            </button>
            <span className="m-offset">{formatOffset(getOffsetMinutes(city.tz, now))}</span>
            {ci === 0 && <span className="ref-badge">REF</span>}
            <button type="button" className="remove-btn m-remove" aria-label={`Remove ${city.name}`} onClick={() => onRemove(city.id)} disabled={cities.length <= 1}>×</button>
          </div>
        ))}
      </div>
      {Array.from({ length: 24 }, (_, h) => (
        <div
          key={h}
          className={`m-row${h === currentRefHour ? ' is-now-row' : ''}`}
          style={{ gridTemplateColumns: `52px repeat(${cities.length}, 1fr)` }}
          role="row"
        >
          <div className="m-hour-label">{formatCellHour(h, format)}</div>
          {cities.map((city, ci) => {
            const cell = matrix[ci][h];
            return (
              <div key={city.id} role="cell" className={cellClass(cell)} title={`${city.name}: ${formatHour(cell.localHour, format)}`}>
                <span className="cell-hour">{formatCellHour(cell.localHour, format)}</span>
                {cell.dayShift !== 0 && <span className="cell-shift">{cell.dayShift > 0 ? '+1' : '−1'}</span>}
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}
"}

{"path":"src/App.tsx","content":"import { useEffect, useMemo, useState } from 'react';
import { CITIES, cityById, type City } from './data/cities';
import { formatHour, getParts, isAwake, zonedHourToUtc, type TimeFormat } from './lib/time';
import CityPicker from './components/CityPicker';
import OverlapSummary, { type Mode } from './components/OverlapSummary';
import { DesktopGrid, MobileGrid, type CellInfo } from './components/Grids';

const STORAGE_KEY = 'tz-overlap-v1';
const DEFAULT_IDS = ['san-francisco', 'denpasar', 'geneva'];

interface Persisted { cityIds: string[]; mode: Mode; wake: number; sleep: number; format: TimeFormat; }

function loadState(): Persisted {
  const fallback: Persisted = { cityIds: DEFAULT_IDS, mode: 'meeting', wake: 7, sleep: 23, format: '12h' };
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return fallback;
    const parsed = JSON.parse(raw) as Partial<Persisted>;
    const ids = Array.isArray(parsed.cityIds)
      ? [...new Set(parsed.cityIds.filter((id): id is string => typeof id === 'string' && !!cityById(id)))]
      : [];
    return {
      cityIds: ids.length > 0 ? ids : fallback.cityIds,
      mode: parsed.mode === 'base' ? 'base' : 'meeting',
      wake: validHour(parsed.wake, fallback.wake),
      sleep: validHour(parsed.sleep, fallback.sleep),
      format: parsed.format === '24h' ? '24h' : '12h',
    };
  } catch {
    return fallback;
  }
}

function validHour(v: unknown, fallback: number): number {
  return typeof v === 'number' && Number.isInteger(v) && v >= 0 && v <= 23 ? v : fallback;
}

function HourSelect({ id, label, value, format, onChange }: { id: string; label: string; value: number; format: TimeFormat; onChange: (v: number) => void }) {
  return (
    <label className="setting" htmlFor={id}>
      <span>{label}</span>
      <select id={id} value={value} onChange={(e) => onChange(Number(e.target.value))}>
        {Array.from({ length: 24 }, (_, h) => (
          <option key={h} value={h}>{formatHour(h, format)}</option>
        ))}
      </select>
    </label>
  );
}

export default function App() {
  const [initial] = useState<Persisted>(loadState);
  const [cityIds, setCityIds] = useState<string[]>(initial.cityIds);
  const [mode, setMode] = useState<Mode>(initial.mode);
  const [wake, setWake] = useState(initial.wake);
  const [sleep, setSleep] = useState(initial.sleep);
  const [format, setFormat] = useState<TimeFormat>(initial.format);
  const [now] = useState(() => new Date());

  useEffect(() => {
    const state: Persisted = { cityIds, mode, wake, sleep, format };
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch { /* storage unavailable */ }
  }, [cityIds, mode, wake, sleep, format]);

  const cities = useMemo(
    () => cityIds.map(cityById).filter((c): c is City => !!c),
    [cityIds],
  );
  const ref = cities[0];

  const { matrix, meetingFlags, baseFlags, currentRefHour } = useMemo(() => {
    const empty = { matrix: [] as CellInfo[][], meetingFlags: Array(24).fill(false) as boolean[], baseFlags: new Map<string, boolean[]>(), currentRefHour: -1 };
    if (!ref) return empty;
    const refParts = getParts(ref.tz, now);
    const instants = Array.from({ length: 24 }, (_, h) => zonedHourToUtc(refParts.year, refParts.month, refParts.day, h, ref.tz));

    const local: number[][] = cities.map((city) => instants.map((d) => getParts(city.tz, d).hour));
    const shifts: number[][] = cities.map((city) =>
      instants.map((d) => {
        const p = getParts(city.tz, d);
        const diff = Date.UTC(p.year, p.month - 1, p.day) - Date.UTC(refParts.year, refParts.month - 1, refParts.day);
        return Math.round(diff / 86400000);
      }),
    );

    const meeting = Array.from({ length: 24 }, (_, h) => cities.every((_, ci) => isAwake(local[ci][h], wake, sleep)));
    const base = new Map<string, boolean[]>();
    cities.slice(1).forEach((city, i) => {
      const ci = i + 1;
      base.set(city.id, Array.from({ length: 24 }, (_, h) => isAwake(local[0][h], wake, sleep) && isAwake(local[ci][h], wake, sleep)));
    });

    const cells: CellInfo[][] = cities.map((city, ci) =>
      Array.from({ length: 24 }, (_, h) => ({
        localHour: local[ci][h],
        dayShift: shifts[ci][h],
        awake: isAwake(local[ci][h], wake, sleep),
        overlap: mode === 'meeting'
          ? meeting[h]
          : ci === 0
            ? isAwake(local[0][h], wake, sleep)
            : (base.get(city.id)?.[h] ?? false),
      })),
    );
    return { matrix: cells, meetingFlags: meeting, baseFlags: base, currentRefHour: refParts.hour };
  }, [cities, ref, now, wake, sleep, mode]);

  const addCity = (id: string) => setCityIds((prev) => (prev.includes(id) ? prev : [...prev, id]));
  const removeCity = (id: string) => setCityIds((prev) => (prev.length <= 1 ? prev : prev.filter((c) => c !== id)));
  const promote = (id: string) => setCityIds((prev) => [id, ...prev.filter((c) => c !== id)]);

  return (
    <div className="app">
      <header className="hero">
        <div className="hero-inner">
          <p className="hero-eyebrow">Timezone overlap checker</p>
          <h1>muse-wonder-1.0</h1>
          <p className="hero-sub">Find the hours when everyone is awake — across every city your team calls home. Times are anchored to the reference city; offsets use today&apos;s date, so daylight saving is handled for you.</p>
        </div>
      </header>

      <main className="shell">
        <section className="controls card">
          <div className="mode-toggle" role="group" aria-label="Overlap mode">
            <button type="button" className={mode === 'meeting' ? 'active' : ''} aria-pressed={mode === 'meeting'} onClick={() => setMode('meeting')}>
              Meeting mode
            </button>
            <button type="button" className={mode === 'base' ? 'active' : ''} aria-pressed={mode === 'base'} onClick={() => setMode('base')}>
              Base mode
            </button>
          </div>
          <p className="mode-hint">
            {mode === 'meeting'
              ? 'One shared window: hours when every selected city is awake at once.'
              : `Per-city windows: each city is compared only against ${ref ? ref.name : 'the reference city'}.`}
          </p>

          <div className="settings-grid">
            <HourSelect id="wake" label="Wake-up hour" value={wake} format={format} onChange={setWake} />
            <HourSelect id="sleep" label="Sleep hour" value={sleep} format={format} onChange={setSleep} />
            <div className="setting">
              <span id="format-label">Time format</span>
              <div className="mode-toggle small" role="group" aria-labelledby="format-label">
                <button type="button" className={format === '12h' ? 'active' : ''} aria-pressed={format === '12h'} onClick={() => setFormat('12h')}>12h</button>
                <button type="button" className={format === '24h' ? 'active' : ''} aria-pressed={format === '24h'} onClick={() => setFormat('24h')}>24h</button>
              </div>
            </div>
          </div>
          <p className="awake-note">Awake window: <strong>{formatHour(wake, format)} — {formatHour(sleep, format)}</strong> local time in every city{wake > sleep ? ' (overnight)' : ''}. Click any city name to make it the reference.</p>

          <CityPicker selectedIds={cityIds} onAdd={addCity} />
          <p className="catalog-note">{CITIES.length} cities in the catalog · {cities.length} selected</p>
        </section>

        <OverlapSummary mode={mode} cities={cities} meetingFlags={meetingFlags} baseFlags={baseFlags} format={format} />

        <section className="card grid-card">
          <DesktopGrid cities={cities} matrix={matrix} format={format} now={now} currentRefHour={currentRefHour} onPromote={promote} onRemove={removeCity} />
          <MobileGrid cities={cities} matrix={matrix} format={format} now={now} currentRefHour={currentRefHour} onPromote={promote} onRemove={removeCity} />
          <div className="legend">
            <span><i className="swatch sw-overlap" /> Overlap</span>
            <span><i className="swatch sw-awake" /> Awake</span>
            <span><i className="swatch sw-sleep" /> Asleep</span>
            <span className="legend-shift">+1 / −1 = next / previous day</span>
          </div>
        </section>

        <p className="hint">{mode === 'meeting' ? 'Green cells = everyone awake' : `Green cells = awake together with ${ref ? ref.name : 'the reference city'}`}</p>
      </main>

      <footer className="footer">Offsets computed from the current date via the Intl timezone database — fractional offsets (e.g. Kathmandu UTC+5:45) included.</footer>
    </div>
  );
}
"}

