{"path":"src/styles.css","content":":root {
  --ink: #17251f;
  --ink-soft: #43554c;
  --paper: #eef1ec;
  --card: #ffffff;
  --line: #d8dfd6;
  --green: #11935e;
  --green-dark: #0b6e45;
  --green-bg: #18a566;
  --sleep-bg: #eef0ec;
  --sleep-text: #a8b3aa;
  --awake-bg: #fdfcf7;
  --warn: #9a3412;
  --warn-bg: #fdf0e7;
  --radius: 10px;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: ui-sans-system, -apple-system, "Segoe UI", Helvetica, sans-serif;
  background: var(--paper);
  color: var(--ink);
