.hero { background: #14231d; color: #edf3ee; border-bottom: 4px solid var(--green); }
.hero-inner { max-width: 1180px; margin: 0 auto; padding: 34px 20px 28px; }
.hero-eyebrow { margin: 0 0 6px; font-size: 12px; letter-spacing: .14em; text-transform: uppercase; color: #9dc8b2; font-weight: 700; }
.hero h1 { margin: 0; font-family: Georgia, "Iowan Old Style", "Times New Roman", serif; font-size: clamp(34px, 5vw, 52px); font-weight: 600; letter-spacing: -.01em; }
.hero-sub { margin: 10px 0 0; max-width: 640px; color: #c3d4c9; line-height: 1.55; font-size: 15px; }

.shell { max-width: 1180px; margin: 0 auto; padding: 20px 20px 8px; display: grid; gap: 16px; }
.card { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; }

.mode-toggle { display: inline-flex; background: #e7ede6; border: 1px solid var(--line); border-radius: 999px; padding: 3px; gap: 2px; }
.mode-toggle button { border: 0; background: transparent; padding: 8px 16px; border-radius: 999px; font: inherit; font-size: 14px; font-weight: 600; color: var(--ink-soft); cursor: pointer; }
.mode-toggle button.active { background: var(--ink); color: #fff; }
.mode-toggle.small button { padding: 6px 12px; font-size: 13px; }
.mode-hint { margin: 10px 0 0; color: var(--ink-soft); font-size: 14px; }

.settings-grid { display: flex; flex-wrap: wrap; gap: 18px 28px; margin-top: 18px; align-items: end; }
.setting { display: grid; gap: 6px; font-size: 13px; font-weight: 600; color: var(--ink-soft); }
.setting select { font: inherit; font-size: 15px; color: var(--ink); padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; background: #fff; min-width: 130px; }
.awake-note { margin: 14px 0 0; font-size: 14px; color: var(--ink-soft); }
.awake-note strong { color: var(--ink); }

.picker { position: relative; margin-top: 20px; max-width: 440px; }
.picker-label { display: block; font-size: 13px; font-weight: 600; color: var(--ink-soft); margin-bottom: 6px; }
.picker-box { position: relative; }
.picker-box input { width: 100%; font: inherit; font-size: 15px; padding: 10px 34px 10px 12px; border: 1px solid var(--line); border-radius: 8px; background: #fff; color: var(--ink); }
.picker-box input:focus { outline: 2px solid var(--green); outline-offset: 1px; }
.picker-clear { position: absolute; right: 6px; top: 50%; transform: translateY(-50%); border: 0; background: transparent; font-size: 20px; cursor: pointer; color: var(--ink-soft); line-height: 1; }
.picker-list { position: absolute; z-index: 20; left: 0; right: 0; top: calc(100% + 6px); margin: 0; padding: 6px; list-style: none; background: #fff; border: 1px solid var(--line); border-radius: 10px; box-shadow: 0 16px 40px rgba(23,37,31,.18); max-height: 280px; overflow: auto; }
.picker-item { width: 100%; display: flex; justify-content: space-between; gap: 12px; text-align: left; border: 0; background: transparent; padding: 9px 10px; border-radius: 7px; font: inherit; cursor: pointer; }
.picker-item:hover { background: #eaf4ee; }
.picker-city { font-weight: 600; font-size: 14px; }
.picker-meta { font-size: 12px; color: var(--ink-soft); white-space: nowrap; }
.picker-empty { padding: 10px; font-size: 14px; color: var(--ink-soft); }
.catalog-note { margin: 10px 0 0; font-size: 12px; color: var(--ink-soft); }

.summary { background: #14231d; color: #edf3ee; border-radius: var(--radius); padding: 16px 18px; }
.summary-list { margin: 0; padding: 0; list-style: none; display: grid; gap: 10px; }
.summary-line { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; margin: 0; font-size: 15px; }
.summary-count { font-size: 20px; font-weight: 800; color: #5fd69d; }
.summary-city { font-weight: 700; }
.summary-detail { color: #c3d4c9; }
.summary .warning { color: #f5b58a; font-weight: 600; }
.range-badges { display: inline-flex; flex-wrap: wrap; gap: 6px; }
.range-badge { background: var(--green-bg); color: #fff; font-weight: 700; font-size: 13px; padding: 4px 10px; border-radius: 999px; white-space: nowrap; }
.muted-line { color: #c3d4c9; }

.grid-card { padding: 14px; overflow: hidden; }
.grid-wrap { width: 100%; }

/* Desktop grid */
.desktop-grid { display: block; }
.d-row { display: grid; grid-template-columns: 168px repeat(24, minmax(26px, 1fr)) 34px; gap: 3px; align-items: stretch; margin-bottom: 3px; }
.d-header { align-items: end; margin-bottom: 6px; }
.d-corner { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-soft); padding-bottom: 4px; }
.d-hour { font-size: 10px; text-align: center; color: var(--ink-soft); font-weight: 600; padding-bottom: 4px; }
.d-hour.is-now { color: var(--green-dark); font-weight: 800; }
.city-label { display: flex; flex-direction: column; justify-content: center; gap: 1px; padding-right: 8px; min-width: 0; }
.city-name { border: 0; background: none; padding: 0; font: inherit; font-size: 14px; font-weight: 700; color: var(--ink); text-align: left; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.city-name:hover { color: var(--green-dark); text-decoration: underline; }
.city-sub { font-size: 11px; color: var(--ink-soft); display: flex; align-items: center; gap: 6px; }
.city-offset { font-size: 11px; color: var(--ink-soft); font-variant-numeric: tabular-nums; }
.ref-badge { background: var(--ink); color: #fff; font-size: 9px; font-weight: 800; letter-spacing: .08em; padding: 2px 6px; border-radius: 4px; }

.cell { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 44px; border-radius: 6px; font-variant-numeric: tabular-nums; border: 1px solid transparent; }
.cell-hour { font-size: 12px; line-height: 1; }
.cell-shift { font-size: 8px; line-height: 1; margin-top: 2px; opacity: .75; }
.cell-sleep { background: var(--sleep-bg); color: var(--sleep-text); }
.cell-awake { background: var(--awake-bg); color: var(--ink); border-color: #e8e4d4; }
.cell-overlap { background: var(--green-bg); color: #fff; border-color: var(--green-dark); }
.cell-overlap .cell-hour { font-weight: 800; font-size: 13px; }
.cell.is-now-col { box-shadow: inset 0 0 0 2px var(--ink); }
.remove-btn { border: 0; background: transparent; font-size: 20px; line-height: 1; color: #b0bab1; cursor: pointer; border-radius: 6px; align-self: center; height: 30px; }
.remove-btn:hover:not(:disabled) { color: #b3261e; background: #fdecea; }
.remove-btn:disabled { opacity: .3; cursor: not-allowed; }

/* Mobile grid */
.mobile-grid { display: none; }
.legend { display: flex; flex-wrap: wrap; gap: 8px 20px; margin-top: 14px; font-size: 13px; color: var(--ink-soft); align-items: center; }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.swatch { width: 14px; height: 14px; border-radius: 4px; display: inline-block; }
.sw-overlap { background: var(--green-bg); }
.sw-awake { background: var(--awake-bg); border: 1px solid #e8e4d4; }
.sw-sleep { background: var(--sleep-bg); }
.legend-shift { margin-left: auto; }

.hint { text-align: center; font-size: 14px; font-weight: 600; color: var(--green-dark); margin: 2px 0 0; }
.footer { max-width: 1180px; margin: 0 auto; padding: 10px 20px 30px; font-size: 12px; color: var(--ink-soft); text-align: center; }

@media (max-width: 767px) {
  .shell { padding: 14px 12px 4px; }
  .card { padding: 14px; }
  .desktop-grid { display: none; }
  .mobile-grid { display: block; }
  .m-header, .m-row { display: grid; gap: 3px; margin-bottom: 3px; align-items: stretch; }
  .m-corner { font-size: 10px; color: var(--ink-soft); display: flex; align-items: end; justify-content: center; padding-bottom: 4px; font-weight: 700; }
  .m-city { display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 4px 2px 6px; text-align: center; min-width: 0; }
  .m-name { text-align: center; font-size: 12px; white-space: normal; overflow: visible; }
  .m-offset { font-size: 10px; color: var(--ink-soft); }
  .m-remove { height: 22px; font-size: 16px; }
  .m-hour-label { font-size: 11px; font-weight: 700; color: var(--ink-soft); display: flex; align-items: center; justify-content: center; font-variant-numeric: tabular-nums; }
  .m-row.is-now-row .m-hour-label { color: var(--green-dark); }
  .m-row.is-now-row .cell { box-shadow: inset 0 0 0 2px var(--ink); }
  .mobile-grid .cell { min-height: 30px; }
  .legend-shift { margin-left: 0; }
}
